package supplies;

/** Exact case-sensitive value; retain the supplied String without normalization. */
public record ItemCode(String value) {
    public ItemCode {
        if (value == null || !value.matches("[A-Z][A-Z0-9]{0,7}"))
            throw new IllegalArgumentException("code");
    }
}

package supplies;

import java.util.Arrays;
import java.util.StringJoiner;

/** Preserved parallel-array implementation: retain as the behavior oracle. */
public final class LegacySupplyRequest {
    private final String destination;
    private final int service;
    private final String[] codes;
    private final int[] units;
    public LegacySupplyRequest(String destination, int service, String[] codes, int[] units) {
        if (destination == null || !destination.matches("[A-Z]{1,12}"))
            throw new IllegalArgumentException("destination");
        if (service < 0 || service > 2) throw new IllegalArgumentException("service");
        if (codes == null || units == null || codes.length != units.length || codes.length > 64)
            throw new IllegalArgumentException("items");
        for (int i = 0; i < codes.length; i++) {
            if (codes[i] == null || !codes[i].matches("[A-Z][A-Z0-9]{0,7}"))
                throw new IllegalArgumentException("code");
            if (units[i] < 1 || units[i] > 999) throw new IllegalArgumentException("units");
        }
        this.destination = destination;
        this.service = service;
        this.codes = codes.clone();
        this.units = units.clone();
    }
    public String destination() { return destination; }
    public int serviceCode() { return service; }
    public int dispatchMinutes() {
        return switch (service) { case 0 -> 180; case 1 -> 60; default -> 30; };
    }
    public String[] itemCodes() { return codes.clone(); }
    public int[] quantities() { return units.clone(); }
    public String toLegacy() {
        StringJoiner body = new StringJoiner(";");
        for (int i = 0; i < codes.length; i++) body.add(codes[i] + ":" + units[i]);
        return destination + "|" + service + "|" + body;
    }
    public static LegacySupplyRequest parse(String row) {
        try {
            if (row == null) throw new IllegalArgumentException("row");
            String[] fields = row.split("\\|", -1);
            if (fields.length != 3 || !fields[1].matches("[012]"))
                throw new IllegalArgumentException("row");
            String[] entries = fields[2].isEmpty() ? new String[0] : fields[2].split(";", -1);
            String[] codes = new String[entries.length];
            int[] units = new int[entries.length];
            for (int i = 0; i < entries.length; i++) {
                String[] pair = entries[i].split(":", -1);
                if (pair.length != 2 || !pair[1].matches("[1-9][0-9]{0,2}"))
                    throw new IllegalArgumentException("row");
                codes[i] = pair[0];
                units[i] = Integer.parseInt(pair[1]);
            }
            return new LegacySupplyRequest(fields[0], Integer.parseInt(fields[1]), codes, units);
        } catch (IllegalArgumentException error) {
            throw new IllegalArgumentException("row");
        }
    }
    @Override public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof LegacySupplyRequest request)) return false;
        return destination.equals(request.destination) && service == request.service
            && Arrays.equals(codes, request.codes) && Arrays.equals(units, request.units);
    }
    @Override public int hashCode() {
        int result = 31 * (31 + destination.hashCode()) + service;
        for (int i = 0; i < codes.length; i++)
            result = 31 * result + 31 * codes[i].hashCode() + units[i];
        return result;
    }
}

package supplies;

import java.util.ArrayList;
import java.util.StringJoiner;

/** Interpret and produce the old transport shape at this boundary. */
public final class RequestCodec {
    private RequestCodec() {}
    public static SupplyRequest decode(String row) {
        try {
            if (row == null) throw new IllegalArgumentException("row");
            String[] fields = row.split("\\|", -1);
            if (fields.length != 3 || !fields[1].matches("[012]"))
                throw new IllegalArgumentException("row");
            String[] entries = fields[2].isEmpty() ? new String[0] : fields[2].split(";", -1);
            ArrayList<RequestLine> lines = new ArrayList<>();
            for (String entry : entries) {
                String[] pair = entry.split(":", -1);
                if (pair.length != 2 || !pair[1].matches("[1-9][0-9]{0,2}"))
                    throw new IllegalArgumentException("row");
                lines.add(new RequestLine(new ItemCode(pair[0]), Integer.parseInt(pair[1])));
            }
            return SupplyRequest.fromLines(fields[0], ServiceLevel.fromCode(Integer.parseInt(fields[1])), lines);
        } catch (IllegalArgumentException error) {
            throw new IllegalArgumentException("row");
        }
    }
    public static String encode(SupplyRequest request) {
        if (request == null) throw new IllegalArgumentException("request");
        StringJoiner body = new StringJoiner(";");
        for (RequestLine line : request.lines())
            body.add(line.code().value() + ":" + line.units());
        return request.destination() + "|" + request.serviceCode() + "|" + body;
    }
}

package supplies;

public record RequestLine(ItemCode code, int units) {
    public RequestLine {
        if (code == null) throw new IllegalArgumentException("code");
        if (units < 1 || units > 999) throw new IllegalArgumentException("units");
    }
}

package supplies;

/** Finite type codes and their own dispatch rule. */
public enum ServiceLevel {
    STANDARD(0, 180), RUSH(1, 60), EXPRESS(2, 30);
    private final int code;
    private final int minutes;
    ServiceLevel(int code, int minutes) { this.code = code; this.minutes = minutes; }
    public int code() { return code; }
    public int dispatchMinutes() { return minutes; }
    public static ServiceLevel fromCode(int code) {
        return switch (code) {
            case 0 -> STANDARD;
            case 1 -> RUSH;
            case 2 -> EXPRESS;
            default -> throw new IllegalArgumentException("service");
        };
    }
}

package supplies;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;

/** Value with an owned, ordered snapshot of immutable line values. */
public final class SupplyRequest {
    private final String destination;
    private final ServiceLevel service;
    private final List<RequestLine> lines;
    public SupplyRequest(String destination, int service, String[] codes, int[] units) {
        this(requireDestination(destination), ServiceLevel.fromCode(service), toLines(codes, units));
    }
    private SupplyRequest(String destination, ServiceLevel service, List<RequestLine> lines) {
        this.destination = requireDestination(destination);
        if (service == null) throw new IllegalArgumentException("service");
        if (lines == null || lines.size() > 64 || lines.stream().anyMatch(line -> line == null))
            throw new IllegalArgumentException("lines");
        this.service = service;
        this.lines = List.copyOf(lines);
    }
    private static String requireDestination(String value) {
        if (value == null || !value.matches("[A-Z]{1,12}"))
            throw new IllegalArgumentException("destination");
        return value;
    }
    private static List<RequestLine> toLines(String[] codes, int[] units) {
        if (codes == null || units == null || codes.length != units.length || codes.length > 64)
            throw new IllegalArgumentException("items");
        ArrayList<RequestLine> result = new ArrayList<>();
        for (int i = 0; i < codes.length; i++)
            result.add(new RequestLine(new ItemCode(codes[i]), units[i]));
        return result;
    }
    public static SupplyRequest fromLines(String destination, ServiceLevel service, List<RequestLine> lines) {
        return new SupplyRequest(destination, service, lines);
    }
    public String destination() { return destination; }
    public int serviceCode() { return service.code(); }
    public int dispatchMinutes() { return service.dispatchMinutes(); }
    public List<RequestLine> lines() { return lines; }
    public String[] itemCodes() {
        return lines.stream().map(line -> line.code().value()).toArray(String[]::new);
    }
    public int[] quantities() { return lines.stream().mapToInt(RequestLine::units).toArray(); }
    public String toLegacy() { return RequestCodec.encode(this); }
    @Override public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof SupplyRequest request)) return false;
        return destination.equals(request.destination) && service == request.service && lines.equals(request.lines);
    }
    @Override public int hashCode() {
        int result = 31 * (31 + destination.hashCode()) + service.code();
        for (RequestLine line : lines) result = 31 * result + line.hashCode();
        return result;
    }
    /** Optional feature: combine duplicate codes, retaining first-occurrence order. */
    public SupplyRequest merged() {
        LinkedHashMap<ItemCode, Integer> totals = new LinkedHashMap<>();
        for (RequestLine line : lines) totals.merge(line.code(), line.units(), Integer::sum);
        ArrayList<RequestLine> combined = new ArrayList<>();
        for (var entry : totals.entrySet())
            combined.add(new RequestLine(entry.getKey(), entry.getValue()));
        return fromLines(destination, service, combined);
    }
}
